{
  "tom_tat": "Cảnh báo ghi nhận nỗ lực đăng nhập SSH thất bại với người dùng 'admin' từ IP 10.10.20.62. Hệ thống xác nhận đây là lần đầu tiên có người dùng không tồn tại cố gắng kết nối qua cổng SSH.",
  "du_can_cu": true,
  "ma_attack": [
    "T1110.001",
    "T1078"
  ],
  "bang_chung": [
    "E1",
    "E3"
  ]
}

{
  "tom_tat": "Cảnh báo ghi nhận nỗ lực đăng nhập SSH thất bại với người dùng không tồn tại từ IP nội bộ. Dữ liệu log cho thấy sự cố xác thực liên quan đến nhóm syslog và sshd, nhưng không có bằng chứng cụ thể về việc đoán mật khẩu hay tạo tài khoản mới.",
  "du_can_cu": false,
  "ma_attack": [],
  "bang_chung": [
    "[E1] rule 5710 (level 5): sshd: Attempt to login using a non-existent user; groups: syslog, sshd, authentication_failed",
    "[E3] full_log: sshd[7301]: Invalid user admin from 10.10.20.173 port 50221"
  ]
}

{
  "tom_tat": "Cảnh báo ghi nhận hoạt động tấn công brute force qua SSH từ IP 10.10.20.17, thử đăng nhập với tài khoản không tồn tại (test) lặp lại 12 lần trong vòng 60 giây. Hành vi này cho thấy kẻ thù đang cố gắng xâm nhập hệ thống bằng cách đoán mật khẩu.",
  "du_can_cu": true,
  "ma_attack": [
    "T1110",
    "T1110.001"
  ],
  "bang_chung": [
    "E1",
    "E3"
  ]
}

