{
  "tom_tat": "Cảnh báo ghi nhận thành công xác thực qua SSH từ IP 10.10.20.113 vào tài khoản labops trên máy chủ lab-web01. Sự kiện này cho thấy có người dùng hợp lệ đã đăng nhập từ xa, nhưng không cung cấp bằng chứng về các hành vi gian lận như brute force hay truy cập trái phép.",
  "du_can_cu": false,
  "ma_attack": [],
  "bang_chung": [
    "[E1] rule 5715 (level 3): sshd: authentication success.; groups: syslog, sshd, authentication_success",
    "[E2] agent: lab-web01",
    "[E3] full_log: sshd[3806]: Accepted password for labops from 10.10.20.113 port 46315 ssh2"
  ]
}

